public static void theWinner(Vote[] votes) {
    int[] points = new int[41];   // points[k] = הנקודות של שיר מספר k
    for (int i = 0; i < votes.length; i++) {
        points[votes[i].getFirst()] += 7;
        points[votes[i].getSecond()] += 5;
        points[votes[i].getThird()] += 1;
    }
    int winner = 1;
    for (int k = 2; k <= 40; k++) {
        if (points[k] > points[winner]) {
            winner = k;
        }
    }
    System.out.println(winner);
}

