for (int i = 0; i < v1.length; i++) {
    v1[i] = new Vote(12, 3, 40);
}
System.out.print("סעיף א, בדיקה 1 (כולם בחרו בשיר 12, צריך להדפיס 12): ");
theWinner(v1);
