for (int i = 0; i < v2.length; i++) {
    if (i < 10) {
        v2[i] = new Vote(5, 8, 1);
    } else if (i < 19) {
        v2[i] = new Vote(8, 1, 5);
    } else {
        v2[i] = new Vote(1, 5, 8);
    }
}
System.out.print("סעיף א, בדיקה 2 (שיר 5 הכי הרבה פעמים ראשון, אבל לשיר 8 יותר נקודות, צריך להדפיס 8): ");
theWinner(v2);
Vote[] v3 = new Vote[25];
for (int i = 0; i < v3.length; i++) {
    if (i < 13) {
        v3[i] = new Vote(40, 2, 3);
    } else {
        v3[i] = new Vote(2, 40, 3);
    }
}
System.out.print("סעיף א, בדיקה 3 (צריך להדפיס 40): ");
theWinner(v3);

